import {precision} from './precision.js';
import {curveIntersections,segmentsMayIntersect} from './curve-engine.js';
// Original Siluetra half-edge region adapter, informed by VectorCraft pathops/planar.rs.
// Splits at geometric intersections; retains exact cubic pieces rather than polygonizing output.
import {worldPath,cubic,clone,uid,I} from './core.js';
import {flattenCubic,cubicSlice,nearestOnCubic} from './bezier.js';
const EPS=precision.geometry;
const derivative=(a,b,t)=>{const c=a.out||a,d=b.in||b,u=1-t;return {x:3*u*u*(c.x-a.x)+6*u*t*(d.x-c.x)+3*t*t*(b.x-d.x),y:3*u*u*(c.y-a.y)+6*u*t*(d.y-c.y)+3*t*t*(b.y-d.y)};};
function crossings(a,b){if(!segmentsMayIntersect(a,b))return [];if(a.line&&b.line){const dx=a.b.x-a.a.x,dy=a.b.y-a.a.y,ex=b.b.x-b.a.x,ey=b.b.y-b.a.y;if(Math.abs(dx*ey-dy*ex)<1e-10&&Math.abs((b.a.x-a.a.x)*dy-(b.a.y-a.a.y)*dx)<1e-7){const out=[],project=(p,x)=>((p.x-x.a.x)*(x.b.x-x.a.x)+(p.y-x.a.y)*(x.b.y-x.a.y))/((x.b.x-x.a.x)**2+(x.b.y-x.a.y)**2);for(const [p,t] of [[a.a,0],[a.b,1]]){const u=project(p,b);if(u>=0&&u<=1)out.push([t,u]);}for(const [p,u] of [[b.a,0],[b.b,1]]){const t=project(p,a);if(t>=0&&t<=1)out.push([t,u]);}return out;}}const hits=curveIntersections(a,b).map(h=>[h.t,h.u]);for(const [p,t] of [[a.a,0],[a.b,1]]){const h=nearestOnCubic(b.a,b.b,p);if(h.distance<=EPS)hits.push([t,h.t]);}for(const [p,u] of [[b.a,0],[b.b,1]]){const h=nearestOnCubic(a.a,a.b,p);if(h.distance<=EPS)hits.push([h.t,u]);}return hits;}

const ringArea=pts=>pts.reduce((sum,p,i)=>{const q=pts[(i+1)%pts.length];return sum+p.x*q.y-q.x*p.y;},0)/2;
const contains=(p,pts)=>{let hit=false;for(let i=0,j=pts.length-1;i<pts.length;j=i++){const a=pts[i],b=pts[j];if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)hit=!hit;}return hit;};
export function planarRegions(objects){return planarTopology(objects).regions;}
export function planarTopology(objects){
 if(!objects.length)return {regions:[],fragments:[]};const segs=[];for(const o of objects){if(o.type!=='path'||!o.nodes?.length||o.source||o.construction||o.regionSources)throw Error('Seleccioná trazados base para detectar regiones.');const w=worldPath(o);for(const [subpath,sp] of [w,...w.subpaths||[]].entries())for(let i=0;i<sp.nodes.length-(sp.closed?0:1);i++){let a=sp.nodes[i],b=sp.nodes[(i+1)%sp.nodes.length];const line=!a.out&&!b.in;if(Math.hypot(a.x-b.x,a.y-b.y)<EPS&&line)continue;if(line){a={...a,out:{x:a.x+(b.x-a.x)/3,y:a.y+(b.y-a.y)/3}};b={...b,in:{x:a.x+(b.x-a.x)*2/3,y:a.y+(b.y-a.y)*2/3}};}segs.push({a,b,line,source:o.id,index:i,subpath,edgeId:sp.nodes[i].edgeId||String(i),ts:[0,1]});}}
 if(segs.length>300)throw Error('La detección admite hasta 300 segmentos por operación. Seleccioná una zona menor.');
 for(let i=0;i<segs.length;i++)for(let j=i+1;j<segs.length;j++)for(const [a,b] of crossings(segs[i],segs[j])){segs[i].ts.push(a);segs[j].ts.push(b);}
 const vertices=[],edges=[],edgeMap=new Map(),keyMap=new Map(),vertex=p=>{const key=Math.round(p.x/EPS)+','+Math.round(p.y/EPS);for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){const found=keyMap.get((Math.round(p.x/EPS)+dx)+','+(Math.round(p.y/EPS)+dy));if(found!==undefined&&Math.hypot(vertices[found].p.x-p.x,vertices[found].p.y-p.y)<=EPS)return found;}const id=vertices.length;vertices.push({p:{x:p.x,y:p.y},out:[]});keyMap.set(key,id);return id;};
 for(const seg of segs){const ts=[...new Set(seg.ts.map(t=>Math.round(t*1e10)/1e10))].sort((a,b)=>a-b);for(let j=1;j<ts.length;j++){if(ts[j]-ts[j-1]<1e-9)continue;const [a,b]=cubicSlice(seg.a,seg.b,ts[j-1],ts[j]),from=vertex(a),to=vertex(b);if(from===to)continue;if(seg.line){delete a.out;delete b.in;}const edgeKey=from+':'+to+':'+JSON.stringify([a.out,b.in]),existing=edgeMap.get(edgeKey);if(existing){existing.sources.push(seg.source);existing.reverse.sources.push(seg.source);const ref={source:seg.source,index:seg.index,subpath:seg.subpath,edgeId:seg.edgeId,t0:ts[j-1],t1:ts[j]};existing.refs.push({...ref,forward:true});existing.reverse.refs.push({...ref,forward:false});continue;}const ref={source:seg.source,index:seg.index,subpath:seg.subpath,edgeId:seg.edgeId,t0:ts[j-1],t1:ts[j]},forward={from,to,a,b,source:seg.source,sources:[seg.source],refs:[{...ref,forward:true}],used:false},reverse={from:to,to:from,a:{...clone(b),in:clone(b.out||b),out:clone(b.in||b)},b:{...clone(a),in:clone(a.out||a),out:clone(a.in||a)},source:seg.source,sources:[seg.source],refs:[{...ref,forward:false}],used:false};if(seg.line){delete reverse.a.out;delete reverse.b.in;}forward.reverse=reverse;reverse.reverse=forward;edgeMap.set(edgeKey,forward);edgeMap.set(to+':'+from+':'+JSON.stringify([reverse.a.out,reverse.b.in]),reverse);vertices[from].out.push(forward);vertices[to].out.push(reverse);edges.push(forward,reverse);}}
 for(const v of vertices){for(const e of v.out){const d=derivative(e.a,e.b,0);e.angle=Math.atan2(d.y||e.b.y-e.a.y,d.x||e.b.x-e.a.x);}v.out.sort((a,b)=>a.angle-b.angle);for(let i=1;i<v.out.length;i++)if(Math.abs(v.out[i].angle-v.out[i-1].angle)<1e-10&&v.out[i].to===v.out[i-1].to)throw Error('Hay bordes coincidentes. Uní o quitá duplicados antes de detectar regiones.');}
 const faces=[];for(const seed of edges){if(seed.used)continue;let e=seed,walk=[];for(let i=0;i<=edges.length;i++){if(e.used)break;e.used=true;walk.push(e);const out=vertices[e.to].out,index=out.indexOf(e.reverse);e=out[(index-1+out.length)%out.length];if(e===seed)break;}if(e!==seed||walk.length<2)continue;const walked=new Set(walk);walk=walk.filter(e=>!walked.has(e.reverse));if(walk.length<2)continue;const pts=walk.flatMap(e=>flattenCubic(e.a,e.b,.05).slice(0,-1)),area=ringArea(pts);if(area<=EPS)continue;const nodes=walk.map((e,i)=>{const n={...clone(e.a),nid:uid(),edgeId:uid(),...vertices[e.from].p},prev=walk[(i-1+walk.length)%walk.length];if(prev.b.in)n.in=clone(prev.b.in);else delete n.in;return n;});faces.push({nodes,closed:true,points:pts,area,boundaryFragments:walk.map(e=>({refs:clone(e.refs),nodes:[clone(e.a),clone(e.b)]})),sources:[...new Set(walk.flatMap(e=>e.sources))]});}
 // Nested disconnected loops become compound holes in their immediate enclosing face.
 const parent=new Map();for(const f of faces){const outer=faces.filter(g=>g!==f&&g.area>f.area+EPS&&contains(f.points[0],g.points)).sort((a,b)=>a.area-b.area)[0];if(outer)parent.set(f,outer);}
 const regions=faces.map((f,i)=>({id:uid(),type:'path',name:'Región de prenda '+(i+1),nodes:f.nodes,closed:true,subpaths:faces.filter(g=>parent.get(g)===f).map(g=>({nodes:clone(g.nodes),closed:true})),matrix:I(),fill:'#ffffff',stroke:'#252a29',width:1,opacity:1,category:'construction',semanticType:'garmentRegion',regionSources:f.sources,symmetryExcluded:true,mirrorPolicy:'none'}));
 return {regions,fragments:edges.filter((e,i)=>i%2===0).map(e=>({refs:clone(e.refs),nodes:[clone(e.a),clone(e.b)]})),faces:faces.map((f,i)=>({...f,path:regions[i]}))};
}
